def climb_stairs(n):
 a,b=1,1
 for _ in range(n): a,b=b,a+b
 return a

def frog_jump(heights):
 h=heights
 d=[0]+[10**18]*(len(h)-1)
 for i in range(1,len(h)):
  d[i]=d[i-1]+abs(h[i]-h[i-1])
  if i>1:d[i]=min(d[i],d[i-2]+abs(h[i]-h[i-2]))
 return d[-1]

def frog_jump_k(heights,k):
 h=heights
 d=[0]+[10**18]*(len(h)-1)
 for i in range(1,len(h)):
  for j in range(1,min(k,i)+1):d[i]=min(d[i],d[i-j]+abs(h[i]-h[i-j]))
 return d[-1]

