def lps_length(s):return lcs_length(s,s[::-1])
def min_insertions_palindrome(s):return len(s)-lps_length(s)
def min_insert_delete(a,b):return len(a)+len(b)-2*lcs_length(a,b)

def shortest_common_supersequence(a,b):
 m,n=len(a),len(b);d=[[0]*(n+1) for _ in range(m+1)]
 for i in range(m+1):d[i][0]=i
 for j in range(n+1):d[0][j]=j
