def count_true_parenthesizations(e):
 memo={}
 def f(i,j,w):
  if i>j:return 0
  if i==j:return int((e[i]=='T')==w)
  if (i,j,w) in memo:return memo[i,j,w]
  ans=0
  for k in range(i+1,j,2):
   lt,lf=f(i,k-1,1),f(i,k-1,0);rt,rf=f(k+1,j,1),f(k+1,j,0)
   if e[k]=='&':ans+=lt*rt if w else lt*rf+lf*rt+lf*rf
   elif e[k]=='|':ans+=lt*rt+lt*rf+lf*rt if w else lf*rf
   else:ans+=lt*rf+lf*rt if w else lt*rt+lf*rf
  memo[i,j,w]=ans;return ans
 return f(0,len(e)-1,1)

