CACHE={}
def get_cases(dp):
    if dp not in CACHE:
        raw=generated(dp);fn=META[dp]['fn'];rf=REF[fn]
        cases=[]
        for a in raw:
            cases.append({'args':a,'expected':rf(*a.values())})
        CACHE[dp]=cases
    return CACHE[dp]

def valid(dp,args,actual,expected):
    if dp=='DP 26':
        a,b=args['a'],args['b'];return isinstance(actual,str) and is_subseq(actual,a) and is_subseq(actual,b) and len(actual)==REF['lcs_length'](a,b)
    if dp=='DP 31':
        a,b=args['a'],args['b'];L=len(a)+len(b)-REF['lcs_length'](a,b);return isinstance(actual,str) and is_subseq(a,actual) and is_subseq(b,actual) and len(actual)==L
    if dp=='DP 42':
        a=args['nums'];L=REF['lis_length'](a);return isinstance(actual,list) and len(actual)==L and all(actual[j]<actual[j+1] for j in range(len(actual)-1)) and is_subseq(actual,a)
    if dp=='DP 44':
        want=len(REF['largest_divisible_subset'](args['nums']));return isinstance(actual,list) and len(actual)==want and all(x in args['nums'] for x in actual) and all(x%y==0 or y%x==0 for j,x in enumerate(actual) for y in actual[:j])
    return actual==expected

def is_subseq(x,s):
    it=iter(s);return all(any(c==q for c in it) for q in x)

def serialize_input(args):
    """Competitive-programming-style stdin used by the built-in judge.
    Each named argument is encoded as one JSON value on its own line.
    Scalars, strings, lists, matrices, etc. are therefore unambiguous.
    """
    return ''.join(json.dumps(v, ensure_ascii=False) + '\n' for v in (args or {}).values())

def parse_stdout(stdout):
    """Turn a student's printed answer into a Python value for judging."""
    lines=[line.strip() for line in stdout.splitlines() if line.strip()]
    if not lines:
        raise ValueError("Program produced no output.")
    candidate=lines[-1]
    try:
        return json.loads(candidate)
    except Exception:
        try:
            import ast
            return ast.literal_eval(candidate)
        except Exception:
            return candidate

def run_user(dp,code,cases):
    rows=[]
    for i,t in enumerate(cases,1):
        try:
            cp=subprocess.run(
                [sys.executable,'-I','-u','-c',code],
                input=serialize_input(t['args']),
                capture_output=True,text=True,timeout=10,
                env={'PYTHONIOENCODING':'utf-8'}
            )
        except subprocess.TimeoutExpired:
            rows.append({'i':i,'ok':False,'e':'Time limit exceeded (10s)'})
            continue

        if cp.returncode != 0:
            rows.append({
                'i':i,'ok':False,
                'e':cp.stderr.strip() or 'Python process failed',
                'tb':cp.stderr.strip() or 'Python process failed'
            })
            continue

        try:
            actual=parse_stdout(cp.stdout)
            rows.append({'i':i,'ok':True,'r':actual})
        except Exception as e:
            rows.append({
                'i':i,'ok':False,
                'e':str(e),
                'tb':cp.stdout.strip() or str(e)
            })
    return rows,''


# The frontend calls the local backend directly; no browser Python runtime is used.
served=HTML

class H(BaseHTTPRequestHandler):
    def _j(self,o,code=200):
        b=json.dumps(o,ensure_ascii=False).encode();self.send_response(code);self.send_header('Content-Type','application/json');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
    def do_GET(self):
        if self.path=='/':
            b=served.encode();self.send_response(200);self.send_header('Content-Type','text/html');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
        else:self._j({'error':'not found'},404)
    def do_POST(self):
        try:
            n=int(self.headers.get('Content-Length','0'));body=json.loads(self.rfile.read(n) or b'{}');dp=body.get('dp')
            if self.path=='/cases':
                cs=get_cases(dp);return self._j({'tests':[{'i':i+1,'args':c['args'],'input':serialize_input(c['args']),'expected':c['expected']} for i,c in enumerate(cs)]})
            if self.path=='/run':
                code=body.get('code','')
                try:
                    cp=subprocess.run([sys.executable,'-u','-c',code],input=body.get('stdin',''),capture_output=True,text=True,timeout=10,env={'PYTHONIOENCODING':'utf-8'})
                except subprocess.TimeoutExpired:
                    return self._j({'error':'Time limit exceeded (10 seconds).'},400)
                if cp.returncode!=0:
                    return self._j({'error':cp.stderr.strip() or 'Python process failed.','stdout':cp.stdout,'stderr':cp.stderr},400)
                return self._j({'stdout':cp.stdout,'stderr':cp.stderr})
            if self.path=='/run-tests':
                cs=get_cases(dp);one=cs
                rows,err=run_user(dp,body.get('code',''),one)
                if err:return self._j({'error':err},400)
                by={r['i']:r for r in (rows or [])};
                res=[];passed=0
                for i,c in enumerate(cs,1):
                    r=by.get(i,{})
                    if not r.get('ok'):ok=False;actual=None;detail=r.get('tb',r.get('e','No result'))
                    else:
                        actual=r['r'];ok=valid(dp,c['args'],actual,c['expected']);detail='' if ok else f'Expected {c["expected"]!r}, got {actual!r}'
                    passed+=int(ok);res.append({'i':i,'args':c['args'],'input':serialize_input(c['args']),'expected':c['expected'],'actual':actual,'status':'PASS' if ok else 'FAIL','detail':detail})
                return self._j({'passed':passed,'total':50,'results':res})
            return self._j({'error':'not found'},404)
        except Exception as e:return self._j({'error':traceback.format_exc()},500)

